def aggregate_reward_dicts(
    rewards: list[RewardDict | None],
    metric_name: str,
    aggregate: Callable[[list[NumericReward]], NumericReward],
) -> RewardDict:
    reward_keys = sorted(
        {key for reward in rewards if reward is not None for key in reward}
    )

    if len(reward_keys) <= 1:
        values = [
            0 if reward is None else next(iter(reward.values()), 0)
            for reward in rewards
        ]
        return {metric_name: aggregate(values)}

    return {
        key: aggregate(
            [0 if reward is None else reward.get(key, 0) for reward in rewards]
        )
        for key in reward_keys
    }

class Mean(BaseMetric[RewardDict]):
    @override
    def compute(self, rewards: list[RewardDict | None]) -> RewardDict:
        return aggregate_reward_dicts(
            rewards,
            metric_name="mean",
            aggregate=lambda values: sum(values) / len(values),
        )

async def _verify_with_timeout(
    self, verifier: BaseVerifier, timeout_sec: float | None
) -> VerifierResult:
    try:
        return await asyncio.wait_for(verifier.verify(), timeout=timeout_sec)
    except EnvironmentStartTimeoutError:
        raise
    except TimeoutError as exc:
        raise VerifierTimeoutError(
            f"Verifier execution timed out after {timeout_sec} seconds"
        ) from exc

if self.trial_paths.reward_json_path.exists():
    rewards = self._parse_reward_json()
elif self.trial_paths.reward_text_path.exists():
    rewards = self._parse_reward_text()
else:
    raise RewardFileNotFoundError(
        f"No reward file found at {self.trial_paths.reward_text_path} or {
            self.trial_paths.reward_json_path
        }"
    )

return VerifierResult(rewards=rewards)
